fn int_field(entries: &[(Value, Value)], field: &str) -> Option<usize> {
    match value_field(entries, field) {
        Some(Value::Int(value)) => (*value).try_into().ok(),
        _ => None,
    }
}

fn ref_field(entries: &[(Value, Value)], field: &str) -> Option<String> {
    match value_field(entries, field) {
        Some(Value::Ref(value)) => Some(value.clone()),
        _ => None,
    }
}

fn bool_pair(key: &str, value: bool) -> (Value, Value) {
    (Value::Text(key.to_owned()), Value::Bool(value))
}

fn ref_pair(key: &str, value: &str) -> (Value, Value) {
    (Value::Text(key.to_owned()), Value::Ref(value.to_owned()))
}

fn push_optional_bool(entries: &mut Vec<(Value, Value)>, key: &str, value: Option<bool>) {
