    pub(super) fn open_with(
        path: impl Into<PathBuf>,
        key: PrivateBindingKey,
        clock: Arc<C>,
        ids: Arc<I>,
    ) -> Result<Self, AdmissionError> {
        let path = path.into();
        let mut connection = open_connection(&path)?;
        initialize_schema(&mut connection, &key)?;
        validate_schema(&connection, &key)?;
        let now_ms = clock.now_ms()?;
        recover_on_cold_open(&mut connection, now_ms)?;
        Ok(Self {
            connection: Mutex::new(connection),
            key,
            clock,
            ids,
        })
    }

    pub(super) fn issue(
        &self,
