fn build_package_root(root: &Path, include_dependency: bool) {
    fs::create_dir_all(root).unwrap();
    let manifest = json!({
        "name": "typescript-npm-project", "version": "1.0.0", "private": true,
        "type": "commonjs", "dependencies": {"alpha": "1.0.0"}
    });
    let lock = json!({
        "name": "typescript-npm-project", "version": "1.0.0", "lockfileVersion": 3,
        "requires": true, "packages": {
            "": {"name": "typescript-npm-project", "version": "1.0.0", "dependencies": {"alpha": "1.0.0"}},
            "node_modules/alpha": {"version": "1.0.0"}
        }
    });
    fs::write(
        root.join("package.json"),
        serde_json::to_vec_pretty(&manifest).unwrap(),
    )
    .unwrap();
    fs::write(
        root.join("package-lock.json"),
        serde_json::to_vec_pretty(&lock).unwrap(),
    )
    .unwrap();
    if include_dependency {
        let alpha = root.join("node_modules/alpha");
        fs::create_dir_all(&alpha).unwrap();
        fs::write(
            alpha.join("package.json"),
            r#"{"name":"alpha","version":"1.0.0","main":"index.js","type":"commonjs"}"#,
        )
        .unwrap();
        fs::write(
